import random, time

ENDPOINTS = ["app.zone-a.internal", "app.zone-b.internal"]

def fetch_with_failover(path, timeout=0.8, attempts=3):
    # Shuffle so a dying primary does not herd all retries onto one host.
    hosts = random.sample(ENDPOINTS, len(ENDPOINTS))
    last_err = None
    for i in range(attempts):
        host = hosts[i % len(hosts)]
        try:
            return http_get(f"https://{host}{path}", timeout=timeout)
        except (TimeoutError, ConnectionError) as e:
            last_err = e
            time.sleep(0.05 * (2 ** i))  # bounded backoff, not tight loop
    raise last_err

